    class decrypt_stage_tlm;
        static const int unsigned LATENCY  = 200;
        static const int unsigned II       = 200;
        static const int unsigned SBOXES   = 1;
        // One clock per scheduled step (step 0 = load).
        static const int unsigned CLKS     = LATENCY;

        virtual fw_aes_clk_if vif;
        int unsigned clks_per_op;  // CLKS unless overridden
        int unsigned m_clks;       // clocks spent in op

        function new(virtual fw_aes_clk_if vif, int unsigned clks_per_op = 0);
            this.vif = vif;
            this.clks_per_op = (clks_per_op != 0) ? clks_per_op : CLKS;
        endfunction

        // The result at zero time, then a clock per scheduled step.
        task op(input bit[7:0] key[0:31], input aes_pkg::KeyWidth key_width, input bit[7:0] block_[0:3][0:3], output bit[7:0] result[0:3][0:3]);
            result = aes_pkg::decrypt(key, key_width, block_);
            for (int unsigned step = 0; step < clks_per_op; step++) begin
                @(posedge vif.clk);
                m_clks++;
            end
        endtask
    endclass

